import xarray as xr
import numpy as np
from metpy.units import units
from metpy.interpolate import cross_section

def test_dbz_unit():
    try:
        units.parse_units('dBZ')
        print("dBZ is defined")
    except Exception as e:
        print(f"dBZ is not defined: {e}")
        raise e

if __name__ == "__main__":
    test_dbz_unit()

